pdate(idle,Tick);g.scene="grove";g.feet=g.project.scenes.at("grove").spawn;g.update(idle,Tick);check(g.inventory.at("gold-coin")==1,"one-time entry event cannot repeat on reentry");std::string error;check(g.save(path,error),"v4 event progress saves");StudioGame restored(argv[1]);check(restored.load(path,error)&&restored.flags==g.flags&&restored.firedEvents==g.firedEvents,"flags and fired events restore together");restored.eventScene.clear();restored.update(idle,Tick);check(restored.inventory.at("gold-coin")==1,"reloading cannot duplicate event rewards");auto data=[](std::string path){std::ifstream f(path);return std::string(std::istreambuf_iterator<char>(f),{});}(path);auto at=data.find("\"grove-greeting\"");check(at!=std::string::npos,"event save record exists");data.replace(at,16,"\"unknown-event\"");auto bad=path+".bad";std::ofstream(bad)<<data;auto old=restored.flags;check(!restored.load(bad,error)&&restored.flags==old&&restored.inventory.at("gold-coin")==1,"unknown saved event rejects atomically");
