int percentPixels=0,differentPixels=0;for(int y=0;y<8;y++)for(int x=0;x<6;x++){auto p=g.atlas.pixels[size_t(128+y)*g.atlas.width+30+x],q=g.atlas.pixels[size_t(128+y)*g.atlas.width+186+x];percentPixels+=p.a>0;differentPixels+=p.a!=q.a;}check(percentPixels>0&&differentPixels>0,"percent glyph exists and differs from question mark");Canvas percent;percent.text("100%",0,0);check(percent.draws.back().source.x==30&&percent.draws.back().source.y==128,"percent text uses its own font cell");
